import{_ as n,l as r,o as e,c as i,v as o,p as s,x as l,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"长上下文微调","description":"","frontmatter":{"title":"长上下文微调","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-context-finetune.md","filePath":"llm/long-context-finetune.md","lastUpdated":1789023840000}'),d={name:"llm/long-context-finetune.md"};function A(c,a,m,f,_,g){const t=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="长上下文微调" tabindex="-1">长上下文微调 <a class="header-anchor" href="#长上下文微调" aria-label="Permalink to &quot;长上下文微调&quot;">​</a></h1><div class="epigraph"><p>窗口拉长不是把 SFT 学习率原样跑在 32k 序列上；位置编码要能外推，注意力要付二次方，数据还得真是长依赖，而不是短指令加 padding。</p><footer>—— 对照 Chen 等位置插值、Peng 等 YaRN（2023）、Xiong 等 Effective Long-Context Scaling（2023）、Chen 等 LongLoRA（ICLR 2024）</footer></div><p><a href="/llm/lora-vs-full-lr">上一课</a>把 LoRA 与全参的 \\(\\eta\\) 分开。长度一涨，账变了：显存被激活与 KV 吃掉，有效批次塌成个位数，全参那条「批次要大」的默认先破产；RoPE 下标走出训练窗，不调位置几何，再小的 \\(\\eta\\) 也在拟合 OOD 相位。本课写长上下文微调相对普通指令 SFT 多出来的三件事——位置、计算、数据——并链到已有的 <a href="/llm/yarn">YaRN</a> 与 <a href="/llm/pose">PoSE</a>。不把领域词表（<a href="/llm/domain-adaptation-ft">下一课</a>）混进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基座上下文长度 \\(L_c\\)（如 4k），目标 \\(L_t\\gg L_c\\)。直接在 \\(L_t\\) 上做因果 LM 或 SFT：注意力激活近似 \\(\\Theta(L_t^2)\\)，微批次掉到 1，<a href="/llm/sft-packing-mask">打包</a>若只是拼接短指令，模型从未见到跨万级 token 的真依赖，却付了长序列的算力。同时 <a href="/llm/rope">RoPE</a> 的高频相位在 \\(L\\gt L_c\\) 上卷绕，困惑度在某一长度断崖。</p><p>因此「长上下文微调」若只改 <code>max_length</code> 而不改位置方案、不改数据，得到的是又贵又短视的指令微调。缺口是把<strong>位置外推</strong>、<strong>可承受的注意力</strong>、<strong>长依赖监督</strong>分成可检查的三项。</p><h3 id="短样本装进长窗口不算长微调" tabindex="-1">短样本装进长窗口不算长微调 <a class="header-anchor" href="#短样本装进长窗口不算长微调" aria-label="Permalink to &quot;短样本装进长窗口不算长微调&quot;">​</a></h3><p>把 ShareGPT 平均 1k 的对话 pad 或打包到 32k，统计上仍是短程语言建模。要学「前文第 20k 个 token 的约束」，数据里必须有那种约束：书籍、仓库级代码、多文档问答、长会话纪要。否则窗口只增加噪声键，<a href="/llm/response-only-loss">仅回复损失</a>还在短答案上，模型没有理由去读远处。</p><p><span class="marginnote">Xiong 等人（Meta，2023）强调持续预训练 / 微调时逐步加长，并配上在长程上仍有预测信号的数据。Chen 等人的 LongLoRA 则用移位稀疏注意力降低微调成本，推理可回到稠密。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>位置：先选外推配方再训——线性位置插值、NTK-aware、<a href="/llm/yarn">YaRN</a> 分段缩放，或 <a href="/llm/pose">PoSE</a> 用短物理长度覆盖长相对距离。不要在原 RoPE 上对 \\(L_t\\) 盲外推还指望 SFT 自己「学好位置」。</p><p>计算：满长度全参往往不可行。选项包括：梯度检查点；<a href="/llm/lora">LoRA</a> / LongLoRA 只训适配器与少量层；PoSE 把物理长度锁在 \\(L_c\\)；序列并行。有效批次用累积补回，<strong>不要</strong>因为微批次=1 就把 \\(\\eta\\) 按全参短上下文再降一档直到静止。学习率仍按<a href="/llm/lora-vs-full-lr">LoRA 对全参</a>的参数化选，再为更噪的长序列梯度略保守。</p><p>数据：<a href="/llm/chat-template">模板</a>不变，但样本要真长。书本续写、长仓库指令、需要引用远处段落的问答。损失仍仅回复——若回复本身很短，应设计必须绑定远处证据的回答，否则梯度不经过长程注意力。</p>',13)),(e(),s(h,null,{default:l(()=>[p(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%BD%8D%E7%BD%AE%EF%BC%9API%20%2F%20YaRN%20%2F%20PoSE%22%5D%20--%3E%20T%5B%22%E5%9C%A8%E5%8F%AF%E6%89%BF%E5%8F%97%E9%95%BF%E5%BA%A6%E4%B8%8A%E5%BE%AE%E8%B0%83%22%5D%0A%20%20C%5B%22%E8%AE%A1%E7%AE%97%EF%BC%9ALoRA%20%2F%20%E6%A3%80%E6%9F%A5%E7%82%B9%20%2F%20%E7%A8%80%E7%96%8F%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%20--%3E%20T%0A%20%20D%5B%22%E6%95%B0%E6%8D%AE%EF%BC%9A%E7%9C%9F%E9%95%BF%E4%BE%9D%E8%B5%96%EF%BC%8C%E9%9D%9E%20pad%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20E%5B%22%E9%95%BF%E7%AA%97%E5%9B%B0%E6%83%91%E5%BA%A6%20%2B%20%E7%9F%AD%E7%AA%97%E5%9B%9E%E5%BD%92%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>评测必须双栏：目标长度上的针检索 / 长文 QA，以及原 \\(L_c\\) 上的短指令与通用基准。只报 Needle 会选出牺牲短程的配方。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RoPE 把相对位置写进相位。插值把下标压回训练过的弧长，模型看到的「相对 \\(k\\) 步」重新落在学过的区间；代价是高频分辨力，YaRN 用分频段处理补这块。微调则在新几何下校准注意力温度与内容键的配合：位置对了，内容仍要用长程数据才能把值读过来。</p><p>LongLoRA 的移位使训练时注意力局部化，参数更新针对「能在稀疏图上工作的特征」；推理稠密相当于把训练过的局部模式嵌回全图。这能成，是因为长程依赖往往稀疏，不是因为稀疏训练等价于稠密训练。PoSE 则让位置通道见过大正 \\(\\Delta\\)，内容通道仍是短块语言——对「位置 OOD」有效，对「必须单次看见全文」的任务仍不够。</p><p><span class="marginnote"><a href="/llm/response-only-loss">仅回复</a>在长提示短答案上极度不平衡：几乎全部算力用在条件编码，梯度只从几十个答案 token 回来。需要证据的答案、或对长完成计损失，否则长微调退化成昂贵的短 SFT。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>法律、代码仓库、多轮客服才值得付 \\(L_t\\) 的成本。普通助手 SFT 把窗口开到 128k 却仍用 Alpaca 单轮，是预算浪费。位置配方与基座绑定：换 YaRN 系数等于换任务，需重训。合并 <a href="/llm/lora">LoRA</a> 后推理窗口仍受位置方案限制，不是适配器自动给无限上下文。</p><p>遗忘：长微调若全参、数据又偏书本，短指令格式会掉，要用短数据回放（后课<a href="/llm/continual-replay">持续学习</a>）。本课只要求评测里留下短窗栏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长上下文微调要同时处理位置外推、二次方算力、真长依赖数据。</li><li>短指令 pad 到长窗不是长微调；回复过短则梯度不经过长程。</li><li>位置用 PI / YaRN / PoSE 等已有课；计算用 LoRA、检查点或跳步训练。</li><li>有效批次靠累积维持；\\(\\eta\\) 仍按 LoRA/全参分叉，勿因微批次=1 而学死。</li><li>评测保留短窗回归，避免只优化针检索。</li><li>出处：Peng 等，YaRN，2023；Xiong 等，Effective Long-Context Scaling，2023；Chen 等，LongLoRA，ICLR 2024；Zhu 等，PoSE，ICLR 2024。</li></ul>',10))])}const u=n(d,[["render",A]]);export{B as __pageData,u as default};
